import java.time.*;
import java.time.chrono.*;
import java.time.format.*;
import java.time.temporal.*;
import java.time.zone.*;
import java.util.*;
import java.util.function.Supplier;

public class TimeTypesModern {
  static void probe(String name, Supplier<Object> body) {
    String out;
    try {
      out = String.valueOf(body.get());
    } catch (Throwable t) {
      out = "!" + t.getClass().getName() + ":" + t.getMessage();
    }
    System.out.println(name + "=" + out);
  }

  public static void main(String[] args) {
    probe("period", () -> Period.of(1, 14, 40) + " " + Period.of(1, 14, 40).normalized() + " " + Period.ofWeeks(3) + " " + Period.ZERO + " " + Period.ofMonths(-5) + " " + Period.ofDays(10).multipliedBy(3) + " " + Period.of(1, 2, 3).negated() + " " + Period.of(1, 2, 3).toTotalMonths());
    probe("period-ops", () -> Period.of(1, 2, 3).plus(Period.of(0, 1, 1)) + " " + Period.of(1, 2, 3).minusMonths(5) + " " + Period.of(1, 2, 3).plusYears(2) + " " + Period.of(1, 2, 3).withDays(9) + " " + Period.of(1, 2, 3).isNegative() + " " + Period.of(0, 0, 0).isZero() + " " + Period.of(1, 2, 3).getUnits() + " " + Period.of(1, 2, 3).get(ChronoUnit.MONTHS));
    probe("period-parse", () -> Period.parse("P1Y2M3D") + " " + Period.parse("P2W") + " " + Period.parse("-P1Y2M") + " " + Period.parse("P-1Y2M") + " " + Period.parse("p1w2d"));
    probe("period-parse-bad", () -> Period.parse("P1H"));
    probe("period-between", () -> Period.between(LocalDate.of(2020, 1, 31), LocalDate.of(2021, 3, 1)) + " " + Period.between(LocalDate.of(2021, 3, 1), LocalDate.of(2020, 1, 31)) + " " + LocalDate.of(2020, 1, 31).plus(Period.of(0, 1, 0)));
    probe("period-from", () -> Period.from(Period.ofDays(3)) + " " + Period.from(ChronoUnit.DAYS.getDuration()));
    probe("period-overflow", () -> Period.ofYears(Integer.MAX_VALUE).plusYears(1));
    probe("year", () -> Year.of(2024) + " " + Year.of(2024).isLeap() + " " + Year.isLeap(1900) + " " + Year.of(2023).length() + " " + Year.of(2024).atDay(60) + " " + Year.of(2024).atMonth(2) + " " + Year.of(2024).plusYears(5) + " " + Year.of(-5).minusYears(5) + " " + Year.of(0).get(ChronoField.ERA) + " " + Year.of(0).get(ChronoField.YEAR_OF_ERA));
    probe("year-ops", () -> Year.of(2024).compareTo(Year.of(2025)) + " " + Year.of(2024).isBefore(Year.of(2025)) + " " + Year.of(2000).until(Year.of(2024), ChronoUnit.DECADES) + " " + Year.of(2024).with(ChronoField.YEAR, 1999) + " " + Year.of(2024).plus(1, ChronoUnit.CENTURIES) + " " + Year.of(2024).query(TemporalQueries.precision()) + " " + Year.of(2024).isValidMonthDay(MonthDay.of(2, 29)) + " " + Year.of(2023).isValidMonthDay(MonthDay.of(2, 29)));
    probe("year-parse", () -> Year.parse("2024") + " " + Year.parse("+12345") + " " + Year.parse("-0005"));
    probe("year-bad", () -> Year.of(1000000000));
    probe("year-range", () -> Year.of(2024).range(ChronoField.YEAR_OF_ERA) + " " + Year.of(-3).range(ChronoField.YEAR_OF_ERA) + " " + Year.of(2024).isSupported(ChronoField.DAY_OF_MONTH));
    probe("yearmonth", () -> YearMonth.of(2024, 2) + " " + YearMonth.of(2024, Month.FEBRUARY).lengthOfMonth() + " " + YearMonth.of(2023, 2).lengthOfMonth() + " " + YearMonth.of(2024, 2).atEndOfMonth() + " " + YearMonth.of(2024, 12).plusMonths(2) + " " + YearMonth.of(2024, 1).minusMonths(2) + " " + YearMonth.of(2024, 3).isValidDay(31) + " " + YearMonth.of(-5, 3) + " " + YearMonth.of(12345, 3));
    probe("yearmonth-ops", () -> YearMonth.of(2024, 2).atDay(10) + " " + YearMonth.of(2024, 2).until(YearMonth.of(2026, 5), ChronoUnit.MONTHS) + " " + YearMonth.of(2024, 2).until(YearMonth.of(2026, 5), ChronoUnit.YEARS) + " " + YearMonth.of(2024, 2).with(ChronoField.MONTH_OF_YEAR, 7) + " " + YearMonth.of(2024, 2).compareTo(YearMonth.of(2024, 3)) + " " + YearMonth.of(2024, 2).getLong(ChronoField.PROLEPTIC_MONTH) + " " + YearMonth.from(LocalDate.of(2024, 5, 6)) + " " + YearMonth.of(2024, 2).hashCode());
    probe("yearmonth-parse", () -> YearMonth.parse("2024-02") + " " + YearMonth.parse("+12345-03"));
    probe("yearmonth-bad", () -> YearMonth.of(2024, 13));
    probe("monthday", () -> MonthDay.of(2, 29) + " " + MonthDay.of(Month.JUNE, 5) + " " + MonthDay.of(2, 29).atYear(2023) + " " + MonthDay.of(2, 29).atYear(2024) + " " + MonthDay.of(3, 31).withMonth(4) + " " + MonthDay.of(3, 31).withDayOfMonth(4) + " " + MonthDay.of(3, 31).compareTo(MonthDay.of(4, 1)) + " " + MonthDay.from(LocalDate.of(2024, 5, 6)) + " " + MonthDay.of(2, 29).isValidYear(2023) + " " + MonthDay.of(2, 29).range(ChronoField.DAY_OF_MONTH));
    probe("monthday-parse", () -> MonthDay.parse("--02-29") + " " + MonthDay.parse("--12-01"));
    probe("monthday-bad", () -> MonthDay.of(2, 30));
    probe("monthday-bad2", () -> { try { MonthDay.parse("--13-01"); return "none"; } catch (DateTimeParseException e) { return e.getClass().getSimpleName() + " " + e.getErrorIndex(); } });
    probe("offset-time", () -> OffsetTime.of(LocalTime.of(10, 15, 30), ZoneOffset.ofHours(2)) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).withOffsetSameInstant(ZoneOffset.ofHours(-3)) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).withOffsetSameLocal(ZoneOffset.ofHours(-3)) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).plusHours(15) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).isEqual(OffsetTime.of(12, 0, 0, 0, ZoneOffset.ofHours(2))) + " " + OffsetTime.MIN + " " + OffsetTime.MAX);
    probe("offset-time-ops", () -> OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).until(OffsetTime.of(12, 30, 0, 0, ZoneOffset.ofHours(1)), ChronoUnit.MINUTES) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).compareTo(OffsetTime.of(11, 0, 0, 0, ZoneOffset.ofHours(2))) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).atDate(LocalDate.EPOCH) + " " + OffsetTime.of(10, 0, 0, 0, ZoneOffset.UTC).get(ChronoField.OFFSET_SECONDS) + " " + OffsetTime.parse("10:15:30+01:00") + " " + OffsetTime.parse("10:15Z"));
    probe("odt", () -> { OffsetDateTime o = OffsetDateTime.of(2024, 2, 29, 13, 45, 30, 123456789, ZoneOffset.ofHoursMinutes(5, 30)); return o + " " + o.toInstant() + " " + o.toEpochSecond() + " " + o.withOffsetSameInstant(ZoneOffset.UTC) + " " + o.withOffsetSameLocal(ZoneOffset.UTC) + " " + o.toLocalDate() + " " + o.getDayOfWeek() + " " + o.plusMonths(1) + " " + o.truncatedTo(ChronoUnit.HOURS); });
    probe("odt-ops", () -> { OffsetDateTime a = OffsetDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC), b = OffsetDateTime.of(2024, 1, 1, 1, 0, 0, 0, ZoneOffset.ofHours(2)); return a.compareTo(b) + " " + a.isAfter(b) + " " + a.isEqual(b) + " " + a.equals(b) + " " + a.until(b, ChronoUnit.MINUTES) + " " + OffsetDateTime.timeLineOrder().compare(a, b) + " " + OffsetDateTime.MIN + " " + OffsetDateTime.MAX; });
    probe("odt-parse", () -> OffsetDateTime.parse("2024-02-29T10:15:30+01:00") + " " + OffsetDateTime.parse("2024-02-29T10:15:30.5Z") + " " + OffsetDateTime.parse("2024-02-29T10:15:30-05:30:15"));
    probe("odt-fields", () -> { OffsetDateTime o = OffsetDateTime.of(2024, 2, 29, 13, 45, 30, 0, ZoneOffset.ofHours(1)); return o.getLong(ChronoField.INSTANT_SECONDS) + " " + o.with(ChronoField.OFFSET_SECONDS, 7200) + " " + o.with(ChronoField.INSTANT_SECONDS, 0) + " " + o.range(ChronoField.OFFSET_SECONDS) + " " + o.query(TemporalQueries.offset()) + " " + o.query(TemporalQueries.zoneId()) + " " + o.query(TemporalQueries.zone()); });
    probe("odt-get-bad", () -> OffsetDateTime.of(2024, 2, 29, 13, 45, 30, 0, ZoneOffset.UTC).get(ChronoField.INSTANT_SECONDS));
    probe("zdt-utc", () -> { ZonedDateTime z = ZonedDateTime.of(2024, 2, 29, 13, 45, 30, 0, ZoneId.of("UTC")); return z + " " + z.getZone() + " " + z.getOffset() + " " + z.toInstant() + " " + z.withZoneSameInstant(ZoneOffset.ofHours(3)) + " " + z.withZoneSameLocal(ZoneOffset.ofHours(3)) + " " + z.toOffsetDateTime() + " " + z.toLocalDateTime(); });
    probe("zdt-ny", () -> { ZoneId ny = ZoneId.of("America/New_York"); ZonedDateTime z = ZonedDateTime.of(2024, 7, 4, 12, 0, 0, 0, ny); return z + " " + z.getOffset() + " " + z.toInstant() + " " + z.withZoneSameInstant(ZoneId.of("Europe/Paris")) + " " + z.withZoneSameInstant(ZoneId.of("Asia/Tokyo")) + " " + z.plusMonths(6) + " " + z.plusHours(24 * 130); });
    probe("zdt-gap", () -> { ZoneId ny = ZoneId.of("America/New_York"); return ZonedDateTime.of(2024, 3, 10, 2, 30, 0, 0, ny) + " " + ZonedDateTime.of(2024, 3, 10, 1, 59, 59, 0, ny).plusSeconds(1) + " " + LocalDate.of(2024, 3, 10).atStartOfDay(ny); });
    probe("zdt-overlap", () -> { ZoneId ny = ZoneId.of("America/New_York"); ZonedDateTime z = ZonedDateTime.of(2024, 11, 3, 1, 30, 0, 0, ny); return z + " " + z.withLaterOffsetAtOverlap() + " " + z.withEarlierOffsetAtOverlap() + " " + z.plusHours(1) + " " + z.plusHours(2); });
    probe("zdt-strict", () -> ZonedDateTime.ofStrict(LocalDateTime.of(2024, 3, 10, 2, 30), ZoneOffset.ofHours(-5), ZoneId.of("America/New_York")));
    probe("zdt-strict2", () -> ZonedDateTime.ofStrict(LocalDateTime.of(2024, 7, 10, 2, 30), ZoneOffset.ofHours(-5), ZoneId.of("America/New_York")));
    probe("zdt-eu", () -> { ZoneId p = ZoneId.of("Europe/Paris"); return ZonedDateTime.of(2024, 3, 31, 2, 30, 0, 0, p) + " " + ZonedDateTime.of(2024, 10, 27, 2, 30, 0, 0, p) + " " + ZonedDateTime.of(2024, 6, 1, 0, 0, 0, 0, p).toInstant() + " " + ZonedDateTime.of(2024, 12, 1, 0, 0, 0, 0, p).toInstant(); });
    probe("zdt-au", () -> { ZoneId s = ZoneId.of("Australia/Sydney"); return ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, s) + " " + ZonedDateTime.of(2024, 7, 1, 0, 0, 0, 0, s) + " " + ZonedDateTime.of(2024, 4, 7, 2, 30, 0, 0, s) + " " + ZonedDateTime.of(2024, 10, 6, 2, 30, 0, 0, s); });
    probe("zdt-nz", () -> { ZoneId s = ZoneId.of("Pacific/Auckland"); return ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, s) + " " + ZonedDateTime.of(2024, 7, 1, 0, 0, 0, 0, s) + " " + ZonedDateTime.of(2024, 9, 29, 2, 30, 0, 0, s); });
    probe("zdt-misc", () -> { ZoneId s = ZoneId.of("Asia/Kolkata"); return ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, s) + " " + ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneId.of("America/St_Johns")) + " " + ZonedDateTime.of(2024, 7, 1, 0, 0, 0, 0, ZoneId.of("America/St_Johns")) + " " + ZonedDateTime.of(2024, 7, 1, 0, 0, 0, 0, ZoneId.of("Asia/Kathmandu")); });
    probe("zdt-ops", () -> { ZonedDateTime a = ZonedDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneId.of("UTC")), b = ZonedDateTime.of(2024, 1, 1, 1, 0, 0, 0, ZoneOffset.ofHours(2)); return a.compareTo(b) + " " + a.isAfter(b) + " " + a.isEqual(b) + " " + a.equals(b) + " " + a.until(b, ChronoUnit.MINUTES) + " " + a.hashCode() * 0 + " " + ChronoZonedDateTime.timeLineOrder().compare(a, b); });
    probe("zdt-parse", () -> ZonedDateTime.parse("2024-02-29T10:15:30+01:00[Europe/Paris]") + " " + ZonedDateTime.parse("2024-02-29T10:15:30Z") + " " + ZonedDateTime.parse("2024-02-29T10:15:30+01:00") + " " + ZonedDateTime.parse("2024-07-29T10:15:30-04:00[America/New_York]"));
    probe("zdt-parse-bad", () -> ZonedDateTime.parse("2024-02-29T10:15:30+01:00[Nowhere/City]"));
    probe("zdt-until", () -> { ZoneId ny = ZoneId.of("America/New_York"); ZonedDateTime a = ZonedDateTime.of(2024, 3, 9, 12, 0, 0, 0, ny); ZonedDateTime b = ZonedDateTime.of(2024, 3, 10, 12, 0, 0, 0, ny); return a.until(b, ChronoUnit.HOURS) + " " + a.until(b, ChronoUnit.DAYS) + " " + Duration.between(a, b) + " " + a.plusDays(1) + " " + a.plus(Duration.ofDays(1)) + " " + a.plus(Period.ofDays(1)); });
    probe("zdt-fields", () -> { ZonedDateTime z = ZonedDateTime.of(2024, 7, 4, 12, 0, 0, 0, ZoneId.of("America/New_York")); return z.getLong(ChronoField.INSTANT_SECONDS) + " " + z.get(ChronoField.OFFSET_SECONDS) + " " + z.query(TemporalQueries.zoneId()) + " " + z.query(TemporalQueries.zone()) + " " + z.query(TemporalQueries.offset()) + " " + z.with(ChronoField.HOUR_OF_DAY, 3) + " " + z.with(LocalTime.MIDNIGHT) + " " + z.with(LocalDate.of(2024, 11, 3)) + " " + z.getDayOfYear(); });
    probe("zdt-from", () -> ZonedDateTime.from(OffsetDateTime.of(2024, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC)) + " " + ZonedDateTime.ofInstant(Instant.ofEpochSecond(1700000000L), ZoneId.of("Europe/London")) + " " + Instant.ofEpochSecond(1700000000L).atZone(ZoneId.of("Asia/Tokyo")) + " " + LocalDateTime.ofInstant(Instant.ofEpochSecond(1700000000L), ZoneId.of("America/Los_Angeles")));
    probe("zdt-from-bad", () -> ZonedDateTime.from(LocalDate.EPOCH));
    probe("zoneid", () -> ZoneId.of("Europe/Paris").getRules().isFixedOffset() + " " + ZoneId.of("UTC").getRules().isFixedOffset() + " " + ZoneId.of("UTC+3") + " " + ZoneId.of("GMT-02:30").getRules().getOffset(Instant.EPOCH) + " " + ZoneId.of("UT").getRules() + " " + ZoneId.of("Z").normalized() + " " + ZoneId.of("UTC").normalized() + " " + ZoneId.ofOffset("UTC", ZoneOffset.ofHours(2)) + " " + ZoneId.of("EST", ZoneId.SHORT_IDS) + " " + ZoneId.of("PST", ZoneId.SHORT_IDS));
    probe("zoneid-set", () -> ZoneId.getAvailableZoneIds().contains("Europe/Paris") + " " + ZoneId.getAvailableZoneIds().contains("America/New_York") + " " + ZoneId.getAvailableZoneIds().contains("Nope"));
    probe("zoneid-bad", () -> ZoneId.of("not a zone"));
    probe("zoneid-bad2", () -> ZoneId.of("Nope/Zone"));
    probe("zoneid-bad3", () -> ZoneId.of("UTC+25"));
    probe("rules", () -> { ZoneRules r = ZoneId.of("America/New_York").getRules(); Instant i = Instant.parse("2024-07-04T12:00:00Z"); return r.getOffset(i) + " " + r.getStandardOffset(i) + " " + r.isDaylightSavings(i) + " " + r.getDaylightSavings(i) + " " + r.nextTransition(i).getInstant() + " " + r.previousTransition(i).getInstant() + " " + r.nextTransition(i); });
    probe("rules-valid", () -> { ZoneRules r = ZoneId.of("Europe/Paris").getRules(); return r.getValidOffsets(LocalDateTime.of(2024, 3, 31, 2, 30)) + " " + r.getValidOffsets(LocalDateTime.of(2024, 10, 27, 2, 30)) + " " + r.getValidOffsets(LocalDateTime.of(2024, 6, 1, 12, 0)) + " " + r.getTransition(LocalDateTime.of(2024, 3, 31, 2, 30)) + " " + r.isValidOffset(LocalDateTime.of(2024, 10, 27, 2, 30), ZoneOffset.ofHours(1)); });
    probe("transition-rule", () -> { var rules = ZoneId.of("America/New_York").getRules().getTransitionRules(); return rules.size() + " " + rules.get(0); });
    probe("offset-transition", () -> { var t = ZoneOffsetTransition.of(LocalDateTime.of(2024, 3, 10, 2, 0), ZoneOffset.ofHours(-5), ZoneOffset.ofHours(-4)); return t + " " + t.isGap() + " " + t.getDuration() + " " + t.getDateTimeAfter() + " " + t.getInstant() + " " + t.isValidOffset(ZoneOffset.ofHours(-5)); });
    probe("isofields", () -> { LocalDate d = LocalDate.of(2024, 2, 29); return d.get(IsoFields.QUARTER_OF_YEAR) + " " + d.get(IsoFields.DAY_OF_QUARTER) + " " + d.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR) + " " + d.get(IsoFields.WEEK_BASED_YEAR) + " " + LocalDate.of(2021, 1, 1).get(IsoFields.WEEK_OF_WEEK_BASED_YEAR) + " " + LocalDate.of(2021, 1, 1).get(IsoFields.WEEK_BASED_YEAR) + " " + LocalDate.of(2024, 12, 30).get(IsoFields.WEEK_BASED_YEAR) + " " + LocalDate.of(2024, 12, 30).get(IsoFields.WEEK_OF_WEEK_BASED_YEAR) + " " + IsoFields.QUARTER_YEARS.between(d, d.plusYears(1)) + " " + d.plus(2, IsoFields.QUARTER_YEARS) + " " + d.with(IsoFields.QUARTER_OF_YEAR, 4) + " " + d.with(IsoFields.WEEK_OF_WEEK_BASED_YEAR, 1) + " " + d.range(IsoFields.DAY_OF_QUARTER) + " " + d.range(IsoFields.WEEK_OF_WEEK_BASED_YEAR); });
    probe("weekfields", () -> { LocalDate d = LocalDate.of(2024, 2, 29); WeekFields us = WeekFields.of(Locale.US), iso = WeekFields.ISO; return us + " " + d.get(us.weekOfYear()) + " " + d.get(us.weekOfMonth()) + " " + d.get(us.dayOfWeek()) + " " + d.get(us.weekOfWeekBasedYear()) + " " + d.get(us.weekBasedYear()) + " " + d.get(iso.weekOfYear()) + " " + d.get(iso.weekOfMonth()) + " " + d.get(iso.dayOfWeek()) + " " + d.get(iso.weekOfWeekBasedYear()) + " " + LocalDate.of(2021, 1, 1).get(iso.weekOfYear()) + " " + LocalDate.of(2021, 1, 1).get(iso.weekBasedYear()) + " " + d.with(us.dayOfWeek(), 1) + " " + d.range(us.weekOfMonth()) + " " + d.range(iso.weekOfWeekBasedYear()) + " " + us.dayOfWeek() + " " + iso.weekOfYear().getDisplayName(Locale.US) + " " + WeekFields.SUNDAY_START + " " + WeekFields.of(DayOfWeek.WEDNESDAY, 3); });
    probe("weekfields-locale", () -> WeekFields.of(Locale.UK) + " " + WeekFields.of(Locale.FRANCE) + " " + WeekFields.of(Locale.GERMANY) + " " + WeekFields.of(Locale.JAPAN) + " " + WeekFields.of(Locale.ENGLISH) + " " + WeekFields.of(new Locale("ar", "EG")) + " " + WeekFields.of(new Locale("zh", "CN")));
    probe("julian", () -> { LocalDate d = LocalDate.of(2024, 2, 29); return d.getLong(JulianFields.JULIAN_DAY) + " " + d.getLong(JulianFields.MODIFIED_JULIAN_DAY) + " " + d.getLong(JulianFields.RATA_DIE) + " " + d.with(JulianFields.MODIFIED_JULIAN_DAY, 0) + " " + JulianFields.JULIAN_DAY.range(); });
    probe("chronology", () -> IsoChronology.INSTANCE.getId() + " " + IsoChronology.INSTANCE.date(2024, 2, 29) + " " + IsoChronology.INSTANCE.isLeapYear(2100) + " " + IsoChronology.INSTANCE.eras() + " " + IsoChronology.INSTANCE.eraOf(0) + " " + IsoChronology.INSTANCE.prolepticYear(IsoEra.BCE, 5) + " " + Chronology.of("ISO") + " " + IsoChronology.INSTANCE.dateYearDay(2024, 366) + " " + IsoChronology.INSTANCE.dateEpochDay(19000) + " " + IsoChronology.INSTANCE.period(1, 2, 3) + " " + IsoChronology.INSTANCE.range(ChronoField.DAY_OF_MONTH) + " " + LocalDate.EPOCH.getChronology() + " " + LocalDate.EPOCH.getEra() + " " + LocalDate.of(-5, 1, 1).getEra() + " " + IsoChronology.INSTANCE.getCalendarType());
    probe("chronology-bad", () -> Chronology.of("Nope"));
    probe("chrono-local", () -> { ChronoLocalDate c = LocalDate.of(2024, 2, 29); return c.isLeapYear() + " " + c.lengthOfMonth() + " " + c.until(LocalDate.of(2025, 3, 1)) + " " + c.atTime(LocalTime.NOON) + " " + c.compareTo(LocalDate.of(2024, 3, 1)) + " " + ChronoLocalDate.from(LocalDateTime.of(2024, 2, 29, 1, 0)) + " " + ChronoLocalDate.timeLineOrder().compare(c, LocalDate.EPOCH); });
    probe("chrono-ldt", () -> { ChronoLocalDateTime<?> c = LocalDateTime.of(2024, 2, 29, 12, 0); return c.toLocalDate() + " " + c.isAfter(LocalDateTime.MIN) + " " + c.toEpochSecond(ZoneOffset.UTC) + " " + ChronoLocalDateTime.from(LocalDateTime.MAX) + " " + c.atZone(ZoneId.of("UTC")); });
    probe("textstyle", () -> TextStyle.FULL.isStandalone() + " " + TextStyle.SHORT_STANDALONE.asNormal() + " " + TextStyle.NARROW.asStandalone() + " " + Month.MARCH.getDisplayName(TextStyle.FULL, Locale.ENGLISH) + " " + Month.MARCH.getDisplayName(TextStyle.SHORT, Locale.ENGLISH) + " " + Month.MARCH.getDisplayName(TextStyle.NARROW, Locale.ENGLISH) + " " + DayOfWeek.FRIDAY.getDisplayName(TextStyle.FULL, Locale.US) + " " + DayOfWeek.FRIDAY.getDisplayName(TextStyle.SHORT, Locale.US) + " " + DayOfWeek.FRIDAY.getDisplayName(TextStyle.NARROW, Locale.US));
    probe("temporal-unit", () -> LocalDate.EPOCH.isSupported(ChronoUnit.DAYS) + " " + LocalDate.EPOCH.isSupported(ChronoUnit.HOURS) + " " + LocalTime.NOON.isSupported(ChronoUnit.HOURS) + " " + LocalTime.NOON.isSupported(ChronoUnit.DAYS) + " " + Instant.EPOCH.isSupported(ChronoUnit.DAYS) + " " + Instant.EPOCH.isSupported(ChronoUnit.MONTHS) + " " + Year.of(2000).isSupported(ChronoUnit.MONTHS) + " " + LocalDateTime.MIN.isSupported(ChronoUnit.FOREVER) + " " + ZonedDateTime.now().isSupported(ChronoUnit.ERAS));
    probe("clock-types", () -> { Clock c = Clock.fixed(Instant.parse("2024-02-29T12:00:00Z"), ZoneId.of("America/New_York")); return ZonedDateTime.now(c) + " " + OffsetDateTime.now(c) + " " + OffsetTime.now(c) + " " + Year.now(c) + " " + YearMonth.now(c) + " " + MonthDay.now(c) + " " + LocalDate.now(c) + " " + c; });
    probe("instant-source", () -> InstantSource.fixed(Instant.EPOCH).instant() + " " + InstantSource.fixed(Instant.EPOCH).millis() + " " + InstantSource.fixed(Instant.EPOCH).withZone(ZoneOffset.UTC) + " " + InstantSource.offset(InstantSource.fixed(Instant.EPOCH), Duration.ofHours(1)).instant());
  }
}
